pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddr) public {
        vm.assume(oracleAddr != address(0));
        vm.assume(oracleAddr.code.length > 0);
        // initialize the contract with the fuzzed oracle address
        C.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(oracleAddr);
        // other initialization parameters are irrelevant for oracle() return value
        c.initialize(info);
        address returned = address(c.oracle());
        assertTrue(returned == oracleAddr);
    }
}
contract OracleStub {
    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 1, timestamp: 1, price: Fixed18.wrap(1e18)});
    }
    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 1, timestamp: 1, price: Fixed18.wrap(1e18)});
    }
    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 1, timestamp: 1, price: Fixed18.wrap(1e18)});
    }
}
interface IOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }
    function sync() external returns (OracleVersion memory);
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory);
}
type Fixed18 is int256;

