contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address oracleAddr) public {
        vm.assume(oracleAddr != address(0));
        vm.assume(oracleAddr.code.length > 0);

        // We cannot call initialize directly because it requires specific calldata;
        // instead, we obtain the current oracle and assert that if it was stored via
        // the internal mechanism, the getter must return a contract.
        // The invariant: oracle() must always return an address with code.
