pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddr) public {
        vm.assume(oracleAddr != address(0));
        // deploy a minimal oracle that satisfies IOracleProvider interface
        MockOracle oracle = new MockOracle();
        // initialize c with a product info that uses the mock oracle
        C.ProductInfo memory info = C.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition(PayoffDefinitionLib.PayoffType.PASS_THROUGH, PayoffDefinitionLib.PayoffDirection.LONG, bytes30(0)),
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0.1e18),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1000e18),
            utilizationCurve: JumpRateUtilizationCurve(PackedFixed18.wrap(0), PackedFixed18.wrap(1e18), PackedFixed18.wrap(0.5e18), PackedUFixed18.wrap(0.8e18))
        });
        // We need to become the controller to initialize
        vm.prank(address(this));
        c.initialize(info);
        // Now retrieve the oracle from c
        IOracleProvider retrieved = c.oracle();
        // The original should return the mock oracle address, so call to currentVersion succeeds.
        // The mutant returns address(0), so call to currentVersion reverts.
        bool ok;
        try retrieved.currentVersion() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract MockOracle {
    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
}

