pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracle, address targetPayoffType, uint256 value) public {
        // The fuzzer provides an oracle address, a target payoff type, and a value for the payoff definition.
        // We assume the oracle is a contract that returns a price equal to the fuzzed value.
        vm.assume(oracle != address(0));
        vm.assume(targetPayoffType != address(0));
        // Deploy a minimal oracle that returns the fuzzed value as price.
        FixedOracle fuzzedOracle = new FixedOracle(value);
        // Deploy a payoff definition that simply returns the fuzzed value as a transformation.
        // This will be the identity transformation for the reference contract,
        // so the price should equal the original oracle price.
        IdentityPayoff payoff = new IdentityPayoff();
        // Initialize the contract C with the oracle and an identity payoff definition.
        // We use a simple payoff type that just passes through the oracle price.
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: payoff.getDefinition(),
            oracle: IOracleProvider(address(fuzzedOracle)),
            maintenance: UFixed18Lib.ONE,
            fundingFee: UFixed18Lib.ZERO,
            makerFee: UFixed18Lib.ZERO,
            takerFee: UFixed18Lib.ZERO,
            positionFee: UFixed18Lib.ZERO,
            makerLimit: UFixed18Lib.MAX,
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: Fixed18Lib.ZERO.pack(),
                maxRate: Fixed18Lib.ZERO.pack(),
                targetRate: Fixed18Lib.ZERO.pack(),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });
        c.initialize(info);
        // Now call currentVersion.  The reference contract should return a price equal to the original oracle price
        // (because the identity transformation is applied).  The mutant might skip the transformation and return
        // the raw oracle price, which is the same in this identity case, so we need a non-identity transformation.
        // To actually trigger the bug, we need a non-identity payoff definition.  However, we are limited to
        // the protocol's PayoffDefinitionLib, which expects a specific set of allowed payoff types and a data payload.
        // The simplest universal property is: for any admissible input, the price returned by currentVersion
        // must equal the price returned by the oracle, because we set the transformation to identity.
        // But the mutant also returns the oracle price directly, so identity does not distinguish them.
        // We need a property that holds for ALL inputs in the reference but not in the mutant.
        // The invariant is: calling currentVersion() always applies the payoffDefinition.transform, so
        // the returned price must satisfy that transform(originalPrice) == currentVersion.price.
        // Since the fuzzed payoff is unknown, we cannot compute the transformation in the test.
        // Instead, we assert that the price is not equal to the raw oracle price when the transformation is
        // not identity – but we cannot construct an arbitrary transform.
        // Thus we must use a simpler property: the presence of the transformation is observable when the
        // oracle price changes.  If we call currentVersion twice with the same oracle state, the outputs
        // should be consistent in both versions.  That doesn't expose the bug.
        // The universal difference is that the reference contract's currentVersion().price is always
        // the result of applying the payoff definition to the oracle price, while the mutant's is the raw
        // oracle price.  So we can check that the returned price equals the payoffDefinition.transform
        // applied to the raw oracle price.  Since we control the oracle price but not the transform,
        // we need to know the transform.  The simplest approach is to use a known transform.
        // We deploy a helper that returns a modified price based on a fuzzed offset.
        // Then we can assert that currentVersion().price equals the known transformed value.
        // Because the payoff definition is part of the deployment, we can choose a simple linear transformation.

        // We'll redeploy with a different oracle that allows us to check the property.
        // Actually, we can use the fuzzed oracle from the initial setup.  We'll use a factory to create the
        // contract and inject a deterministic transform.
        // But the initialization can only happen once per C.  So we need a fresh deployment per fuzz run.
        // That's fine; we call setUp which deploys a new C.
        // So we must fuzz the input of the transformation as well.  We'll deploy a custom payoff provider
        // that uses a simple linear transform: newPrice = rawPrice + offset.
        // We pass the offset as fuzz parameter.
    }
}

// Minimal oracle that returns a single fixed version with the given price.
contract FixedOracle is IOracleProvider {
    uint256 private _price;
    constructor(uint256 price_) { _price = price_; }
    function sync() external returns (OracleVersion memory) {
        OracleVersion memory v;
        v.version = 1;
        v.timestamp = block.timestamp;
        v.price = Fixed18.wrap(int256(_price));
        return v;
    }
    function currentVersion() external view returns (OracleVersion memory) {
        OracleVersion memory v;
        v.version = 1;
        v.timestamp = block.timestamp;
        v.price = Fixed18.wrap(int256(_price));
        return v;
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        OracleVersion memory v;
        v.version = 1;
        v.timestamp = block.timestamp;
        v.price = Fixed18.wrap(int256(_price));
        return v;
    }
}

// PayoffDefinitionLib.PayoffType is an enum; we need to provide a valid definition.
// Since we cannot import the library easily, we'll hardcode a simple payoff type that does a linear transform.
// The PayoffDefinition struct expects a payoffType, payoffDirection, and a data bytes30.
// We'll create a helper that produces such a definition with a known transformation.
contract IdentityPayoff {
    function getDefinition() external pure returns (PayoffDefinition memory) {
        // This is a no-op payoff type (e.g., identity).
        // The actual transformation logic is in the library, so we must trust that the payoff type we choose
        // corresponds to identity in the reference and something else in the mutant? No.
        // We must define a property that holds regardless of the payoff definition.
        // The property is: currentVersion().price = payoffDefinition.transform(oracle().currentVersion().price)
        // But we cannot compute the transform in the test without knowing the implementation.
        // However, we can observe that in the reference, the transform is applied; in the mutant, it is not.
        // It is possible that some transform yields the same result as the raw value, so we must avoid that.
        // We can ensure the transform is not identity by using a known scaling factor.
        // We'll create a payoff that multiplies by a factor.
        // The fuzzer provides the factor (except 1).  Then we can assert currentVersion().price == rawPrice * factor
        // for the reference.  The mutant will return rawPrice, so it fails for factor != 1.
        // This requires that the payoff library supports such a multiplication – but we don't know the library.
        // We'll give up on simulating the transform and instead assert over the return value's structure:
        // Since the differential is only in the price field, we can check that price == oraclePrice * something.
        // But the oracle price is fuzzed, and the factor is unknown.
        // The universal property that the reference holds and the bug breaks is:
        // The price returned by currentVersion is always strictly between MIN and MAX? No.
        // The only reliable observable difference is that if the oracle price changes between two versions,
        // the transformation affects the value.  But we only have one version.
        // Let's think: the bug removes the call to _transform.  So any effect of _transform is removed.
        // _transform calls payoffDefinition().transform(oracleVersion.price).  So the mutant always returns
        // the raw oracle price.  Therefore, the reference returns transform(rawPrice), mutant returns rawPrice.
        // The only way to detect this is to have a transform that does something – but we need to guess what
        // transforms the library supports.  Since the fuzzer can't construct arbitrary PayoffDefinition data,
        // we must rely on the fact that the initialization sets the payoffDefinition from the ProductInfo,
        // and we can choose one that results in a known non-identity transform.
        // The solution: we will use a payoff type that the library interprets as a simple passthrough, but
        // we will compare against the oracle's currentVersion price (which is raw).  In the reference,
        // passthrough is identity, so they are equal.  In the mutant, they are also equal.  No difference.
        // So we need a non-identity transform.  The protocol has several payoff types; we can use one that
        // adds a constant.  The constant can be part of the data bytes30.  We'll use a known constant.
        // Since the internal library code is not available, we cannot compute the expected result without
        // mimicking it.  But we don't need to compute the expected result; we can assert that the returned
        // price is NOT equal to the raw oracle price when the transform is known to be non-identity.
        // That is a valid invariant: for a payoff definition that is not identity, the price should differ
        // from the raw oracle price.  The fuzzer cannot change the definition after deployment, so we
        // must deploy with a non-identity definition once.  We'll hardcode a reasonable definition that
        // we know is not identity (e.g., a scalar multiplier of 2).  Since the data format is internal,
        // we'll need to construct the correct bytes30.  We'll assume a simple payload that the library
        // interprets as a multiplication factor.
        // However, the requirement says "Do NOT hard-code a primitive deciding value".  The payoff definition
        // is part of the contract initialization and must be chosen by the fuzzer.  But the fuzzer cannot
        // generate valid PayoffDefinition because its internal structure is hidden.  Thus we must let the
        // fuzzer control the raw data and trust that some of those will be non-identity transforms.
        // A better approach: we can assert that currentVersion().price is always within some relationship
        // to the oracle price, but that doesn't directly expose the bug.
        // Let's reconsider: the bug is that _transform is never called.  So the price returned is exactly
        // oracle().currentVersion().price.  In the reference, it's payoffDefinition().transform(oracle().currentVersion().price).
        // Therefore, the universal property is: currentVersion().price MUST equal payoffDefinition().transform(
        // oracle().currentVersion().price).  To check this, we would need to compute transform ourselves,
        // which is impossible without the library.  But we can observe that the transform is deterministic
        // and depends only on the payoffDefinition and the raw price.  So if we record the returned price
        // and later change the raw price (by updating the oracle), we can check consistency of the transform
        // being applied.  But we cannot update the oracle in C after initialization.
        // We are stuck with the initial configuration.
        // Therefore, the only way to create a property that fails for the mutant and passes for the reference
        // without knowing the internal transform is to use a property that the reference always satisfies
        // because of the transform, even if we don't know the exact result.  For example, if the transform
        // always returns a price that is a multiple of a certain constant, we could check that.
        // But we don't know the transform.
        // Given the constraints, the simplest and most robust approach is to deploy the contract with a
        // payoff definition that we know is not identity, and then check that currentVersion().price is NOT
        // equal to the oracle's current price.  Since the oracle price is fuzzed, and the payoff is fixed
        // to a simple non-identity (e.g., multiply by 2), we can assert inequality.  The "deciding value"
        // here is the fuzzed oracle price, which drives the assertion.  Hard-coding the payoff definition to
        // a known non-identity is acceptable because it is the minimal setup to observe the behavioral difference.
        // The requirement forbids hard-coding a primitive deciding value (amount/id/actor) that directly
        // triggers the bug; it does not forbid configuring the system under test in a constant way to expose
        // the bug.  Here the payoff definition is a configuration, not the deciding input.
        // Therefore, we will deploy a payoff definition that adds a fixed offset (e.g., 1e18) to the price.
        // Then assert that currentVersion().price != rawOraclePrice.
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 priceRaw, int8 direction, uint8 payoffType) public {
        // Admissible domain: priceRaw > 0 (non-zero oracle price), payoffType 1..4 (non-identity),
        // direction -1 or 1. This ensures the payoff definition applies a transformation.
        vm.assume(priceRaw > 0 && priceRaw < type(int256).max);
        vm.assume(payoffType >= 1 && payoffType <= 4);
        vm.assume(direction == int8(-1) || direction == int8(1));

        // Deploy a minimal oracle that returns the fuzzed price
        MockOracle oracle = new MockOracle(int256(priceRaw));
        // Build PayoffDefinition that always transforms (non-identity for type 1..4)
        bytes30 data;
        // For types 1..4 (PASSTHROUGH only for type 0, which we exclude)
        // We just pack payoffType and direction into data to pass validation;
        // the actual transform formula is not important, only that it differs from raw.
        assembly {
            data := or(shl(248, and(payoffType, 0xff)), shl(240, and(direction, 0xff)))
        }

        PayoffDefinition memory payoffDef = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(payoffType),
            PayoffDefinitionLib.PayoffDirection(direction),
            data
        );

        // ProductInfo to initialize C
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: payoffDef,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(0.1e18),
            fundingFee: UFixed18.wrap(0.01e18),
            makerFee: UFixed18.wrap(0.01e18),
            takerFee: UFixed18.wrap(0.01e18),
            positionFee: UFixed18.wrap(0.01e18),
            makerLimit: UFixed18.wrap(1000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0.01e18),
                maxRate: PackedFixed18.wrap(1e18),
                targetRate: PackedFixed18.wrap(0.5e18),
                targetUtilization: PackedUFixed18.wrap(0.8e18)
            })
        });

        // We need to become the controller to initialize
        // Instead, we can directly call initialize by deploying a controller mock
        // But the product expects msg.sender to be IController. We'll use a helper.
        // Deploy a minimal controller that allows initialization.
        MockController ctrl = new MockController();
        vm.prank(address(ctrl));
        c.initialize(info);

        // Now read currentVersion from c and from oracle
        IOracleProvider.OracleVersion memory cVersion = c.currentVersion();
        IOracleProvider.OracleVersion memory rawVersion = oracle.currentVersion();

        // The rule: c's price must differ from the raw oracle price because
        // payoff transformation is non-identity (true for all directions and types we selected).
        // Note: Some rare combinations might yield identity (e.g., if price=0), but we excluded zero.
        // Also, we assume the transform always changes the price for non-zero input.
        // Actually, the transform depends on the library; we simply check inequality.
        assertTrue(Fixed18.unwrap(cVersion.price) != Fixed18.unwrap(rawVersion.price));
    }
}

contract MockOracle {
    int256 immutable price;
    constructor(int256 _price) {
        price = _price;
    }
    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(price));
    }
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(1, block.timestamp, Fixed18.wrap(price));
    }
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(1, block.timestamp, Fixed18.wrap(price));
    }
}

contract MockController is IController {
    // Minimal implementation to satisfy initialization
    IBeacon productBeacon;
    ICollateral collateral_;
    IIncentivizer incentivizer_;
    constructor() {}
    function isProduct(IProduct) external pure returns (bool) { return true; }
    function coordinatorFor(IProduct) external pure returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return address(this); }
    function incentivizer() external view returns (IIncentivizer) { return IIncentivizer(address(this)); }
    function collateral() external view returns (ICollateral) { return ICollateral(address(this)); }
    function productBeacon() external view returns (IBeacon) { return productBeacon; }
    function multiInvoker() external view returns (IMultiInvoker) { return IMultiInvoker(address(0)); }
    function minFundingFee() external view returns (UFixed18) { return UFixed18.wrap(0); }
    function paused() external view returns (bool) { return false; }
    function sync(IOracleProvider.OracleVersion calldata) external { }
    function syncAccount(address, IOracleProvider.OracleVersion calldata) external { }
    function settleAccount(address, Fixed18) external { }
    function settleProduct(UFixed18) external { }
    function liquidatable(address, IProduct) external view returns (bool) { return false; }
    function liquidatableNext(address, IProduct) external view returns (bool) { return false; }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint8 payoffTypeRaw,
        uint8 payoffDirectionRaw,
        int256 oraclePriceRaw
    ) public {
        // Bound raw arguments to valid enum and int256 ranges
        uint8 payoffType = uint8(bound(payoffTypeRaw, 0, 2)); // 3 payoff types
        uint8 payoffDirection = uint8(bound(payoffDirectionRaw, 0, 1)); // 2 directions
        int256 oraclePrice = int256(bound(int256(oraclePriceRaw), -1e30, 1e30));

        // Construct a PayoffDefinition with non-identity transformation
        // Use assembly to pack the struct into bytes32 for storage
        bytes32 payoffStorage;
        assembly {
            let offset := payoffStorage
            mstore(offset, payoffType)
            mstore(add(offset, 1), payoffDirection)
            mstore(add(offset, 2), 0) // data bytes30 (unused but must be zero for identity? Use non-zero to force transform)
            // Actually set non-zero data to ensure non-identity transform
            mstore(add(offset, 4), 0x1234) // some non-zero data
        }

        // Initialize C with a mock oracle and the payoff definition
        // We must call initialize which expects ProductInfo including an oracle address
        // But we cannot deploy a real oracle in fuzz test without a mock.
        // The property is: after full initialization with a valid oracle and payoff,
        // currentVersion().price equals _transform(oracle().currentVersion()).price.
        // Since we cannot fully initialize without oracle contract, we test the difference
        // by directly comparing the behavior of a call through the public method.

        // To test the property, we need to deploy an oracle mock that returns a known price
        // and then observe currentVersion().price after initialization.
        MockOracle mockOracle = new MockOracle();
        mockOracle.setCurrentPrice(Fixed18.wrap(oraclePrice));
        mockOracle.setVersion(1);

        // Build PayoffDefinition with non-identity transform (e.g., negative direction)
        // PayoffType: 0=NONE, 1=CONTRACT, 2=EXTERNAL (we need 1 or 2 for non-trivial? Actually any can have transform)
        // For simplicity, use a type that applies a sign flip on direction=1 (SHORT)
        // The transform in the reference multiplies price by -1 if direction is SHORT.
        // We'll set payoffType=0 (PASSTHROUGH) but direction=1 to see if transform happens.
        // Actually PASSTHROUGH with SHORT still transforms: it flips sign.
        // So we can test with a small variety.
        PayoffDefinition memory payoffDef;
        payoffDef.payoffType = PayoffDefinitionLib.PayoffType(payoffType);
        payoffDef.payoffDirection = PayoffDefinitionLib.PayoffDirection(payoffDirection);
        // Set non-zero data to ensure it's not ignored
        payoffDef.data = bytes30(uint240(0x1234));

        // Initialize the product
        c.initialize(IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: payoffDef,
            oracle: IOracleProvider(address(mockOracle)),
            maintenance: UFixed18.wrap(0.1e18),
            fundingFee: UFixed18.wrap(0.001e18),
            makerFee: UFixed18.wrap(0.001e18),
            takerFee: UFixed18.wrap(0.002e18),
            positionFee: UFixed18.wrap(0.001e18),
