            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });
        // Initialize C through the controller interface: we need a Controller mock that recognizes this product
        MockController controller = new MockController();
        vm.prank(address(controller));
        c.initialize(info);
        // Now call atVersion and verify the returned price equals the raw oracle price (identity transform)
        IOracleProvider.OracleVersion memory result = c.atVersion(version);
        assertEq(Fixed18.unwrap(result.price), rawPrice * 1e18, "atVersion price must equal transformed raw price");
    }
}

contract MockOracle is IOracleProvider {
    uint256 public immutable v;
    int256 public immutable p;
    constructor(uint256 _v, int256 _p) {
        v = _v;
        p = _p;
    }
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(v, uint64(block.timestamp), Fixed18.wrap(p * 1e18));
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(v, uint64(block.timestamp), Fixed18.wrap(p * 1e18));
    }
    function atVersion(uint256 v_) external view returns (OracleVersion memory) {
        require(v_ == v, "wrong version");
        return OracleVersion(v, uint64(block.timestamp), Fixed18.wrap(p * 1e18));
    }
}

contract MockController {
    function isProduct(IProduct) external pure returns (bool) { return true; }
}
